export function CreateFilialForm() {
  const { user } = useAuth();
  const createFilialMethods = useForm<CreateFilialFormSchemaType>({
    resolver: zodResolver(createFilialFormSchema),
  });

  const {
    handleSubmit,
    control,
    register,
    formState: { errors },
    reset,
    setValue,
  } = createFilialMethods;

  async function handleCreateFilial(newFilialData: CreateFilialFormSchemaType) {
    try {
      const response = await fetchWithToken(
        `${process.env.NEXT_PUBLIC_SERVER_URL}/filials/create`,
        {
          method: "POST",
          credentials: "include",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(newFilialData),
        },
      );
      const data = await response.json();

      if (!response.ok) {
        toast.warning(data.message, { style: { fontSize: "1rem" } });
        window.scroll({ top: 0 });
      } else {
        toast.success("Filial criado com sucesso!", {
          style: { fontSize: "1rem" },
        });
        window.scroll({ top: 0 });
        window.scroll({ top: 0 });
        reset();
      }
    } catch {
      toast.error("Erro ao criar filial.");
    }
  }

  return (
    <form
      id="create-filial-form"
