const TimeGrid = ({
  value,
  onChange,
  options,
}: {
  value: number | undefined;
  onChange: (val: number) => void;
  options: { value: number; label: string }[];
}) => {
  return (
    <div className="grid grid-cols-4 gap-2 max-h-[200px] overflow-y-auto p-1 rounded-md border">
      {options.map((opt) => (
        <Button
          key={ opt.value }
          type="button"
          variant={ value === opt.value ? "default" : "outline" }
          size="sm"
          onClick={ () => onChange(opt.value) }
          className={ `
            relative text-xs h-9 transition-all duration-200
            ${value === opt.value ? "ring-2 ring-primary ring-offset-2" : ""}
          ` }
        >
          {opt.label}
        </Button>
      ))}
    </div>
  );
};

const updateNoticeSchema = z
  .object({
    description: z.string().min(1, "Descrição é obrigatória"),
    filialId: z.string().optional(),
    startDate: z.date({ required_error: "Data de início é obrigatória" }),
    endDate: z.date({ required_error: "Data de término é obrigatória" }),
    startHourInMinutes: z.number({
      required_error: "Horário de início é obrigatório",
    }),
    endHourInMinutes: z.number({
      required_error: "Horário de término é obrigatório",
    }),
  })
  .refine(
    (data) => {
      if (data.endDate < data.startDate) return false;
      if (data.endDate.getTime() === data.startDate.getTime()) {
        return data.endHourInMinutes > data.startHourInMinutes;
      }
      return true;
    },
    {
      message: "Data/Hora de término deve ser posterior ao início",
      path: [ "endHourInMinutes" ],
    },
  );

type UpdateNoticeSchemaType = z.infer<typeof updateNoticeSchema>;

interface UpdateNoticeDialogProps {
  notice: Notice | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function UpdateNoticeDialog({
  notice,
  open,
  onOpenChange,
}: UpdateNoticeDialogProps) {
  const { user } = useAuth();
  const { getAccessibleFilialsForCreate } = useAccess();

  const accessibleFilialsObjects =
    user?.role === USER_ROLES.ADMIN || user?.role === USER_ROLES.MASTER
      ? []
      : getAccessibleFilialsForCreate(SYSTEM_MODULES.NOTICES);

  const accessibleFilialsIds =
    accessibleFilialsObjects.length > 0
      ? accessibleFilialsObjects.map((f) => f.filialId)
      : user?.role === USER_ROLES.ADMIN || user?.role === USER_ROLES.MASTER
        ? undefined
        : [];

  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<UpdateNoticeSchemaType>({
    resolver: zodResolver(updateNoticeSchema),
  });

  useEffect(() => {
    if (notice) {
      reset({
        description: notice.description,
        filialId: notice.filialId,
        startDate: new Date(notice.startDate),
        endDate: new Date(notice.endDate),
        startHourInMinutes: notice.startHourInMinutes,
        endHourInMinutes: notice.endHourInMinutes,
      });
    }
  }, [ notice, reset ]);

  const timeOptions = useMemo(() => {
    const opts = [];
    for (let i = 0; i < 24 * 60; i += 30) {
      opts.push({
        value: i,
        label: minutesToHHMM(i),
      });
    }
    opts.push({
      value: 1429,
      label: "23:49",
    });
    return opts.sort((a, b) => a.value - b.value);
  }, []);

  const onSubmit: SubmitHandler<UpdateNoticeSchemaType> = async (data) => {
    if (!notice) return;

    const payload = {
      description: data.description,
      filialId: data.filialId,
      startDate: data.startDate.toISOString(),
      endDate: data.endDate.toISOString(),
      startHourInMinutes: data.startHourInMinutes,
      endHourInMinutes: data.endHourInMinutes,
    };

    const response = await UpdateNotice(notice.noticeId, payload);

    if (response.statusCode === 200) {
      toast.success("Aviso atualizado com sucesso!");
      onOpenChange(false);
      queryClient.invalidateQueries({ queryKey: [ "get-notices" ] });
    } else {
      toast.error(response.message || "Erro ao atualizar aviso");
    }
  };

  return (
    <Dialog open={ open } onOpenChange={ onOpenChange }>
      <DialogContent className="sm:max-w-[800px]">
        <DialogHeader>
          <DialogTitle>Editar Aviso</DialogTitle>
        </DialogHeader>
        <form onSubmit={ handleSubmit(onSubmit) } className="space-y-4">
          <div className="space-y-2">
            <Label>Filial</Label>
            <SelectFilial
              control={ control }
              name="filialId"
              accessibleFilials={ accessibleFilialsIds }
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Descrição</Label>
            <Controller
              name="description"
              control={ control }
              render={ ({ field }) => (
                <Textarea
                  { ...field }
                  id="description"
                  placeholder="Digite o aviso..."
                  className="min-h-[100px]"
                />
              ) }
            />
            {errors.description && (
              <span className="text-destructive text-sm">
                {errors.description.message}
              </span>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-4">
              <div className="space-y-2">
                <Label>Data de Início</Label>
                <Controller
                  name="startDate"
                  control={ control }
                  render={ ({ field }) => (
                    <DatePicker
                      value={ field.value || null }
                      onChange={ field.onChange }
                      modal={ true }
                    />
                  ) }
                />
                {errors.startDate && (
                  <span className="text-destructive text-sm">
                    {errors.startDate.message}
                  </span>
                )}
              </div>

              <div className="space-y-2">
                <Label>Horário Início</Label>
                <Controller
                  name="startHourInMinutes"
                  control={ control }
                  render={ ({ field }) => (
                    <TimeGrid
                      value={ field.value }
                      onChange={ field.onChange }
                      options={ timeOptions }
                    />
                  ) }
                />
                {errors.startHourInMinutes && (
                  <span className="text-destructive text-sm">
                    {errors.startHourInMinutes.message}
                  </span>
                )}
              </div>
            </div>

            <div className="space-y-4">
              <div className="space-y-2">
                <Label>Data de Término</Label>
                <Controller
                  name="endDate"
                  control={ control }
                  render={ ({ field }) => (
                    <DatePicker
                      value={ field.value || null }
                      onChange={ field.onChange }
                      modal={ true }
                    />
                  ) }
                />
                {errors.endDate && (
                  <span className="text-destructive text-sm">
                    {errors.endDate.message}
                  </span>
                )}
              </div>

              <div className="space-y-2">
                <Label>Horário Término</Label>
                <Controller
                  name="endHourInMinutes"
                  control={ control }
                  render={ ({ field }) => (
                    <TimeGrid
                      value={ field.value }
                      onChange={ field.onChange }
                      options={ timeOptions }
                    />
                  ) }
                />
                {errors.endHourInMinutes && (
                  <span className="text-destructive text-sm">
                    {errors.endHourInMinutes.message}
                  </span>
                )}
              </div>
            </div>
          </div>

          <Button type="submit" className="w-full" size="lg">
            Atualizar Aviso
          </Button>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect } from "react";
import { useForm, useFieldArray, FormProvider } from "react-hook-form";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Training } from "@/utils/@types/training";
import { UpdateTraining } from "@/services/trainings.service";
import { Loader2 } from "lucide-react";
import { UpdateTrainingPayload } from "./TrainingPaymentMethodDialog";
import { parseStringToCents } from "@/utils/parseStringToCents";
import { toast } from "sonner";
import { queryClient } from "@/app/(main)/layout";
import { FinancialInputSection } from "./FinancialInputSection";
import { CreateTrainingDataType } from "@/lib/zod/CreateTrainingValidation";

interface EditTrainingFinancialsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  training: Training;
  payerType: "TRAINEE" | "VOLUNTEER";
  onSuccess: (updatedTraining: Training) => void;
}

export default function EditTrainingFinancialsDialog({
  open,
  onOpenChange,
  training,
  payerType,
  onSuccess,
}: EditTrainingFinancialsDialogProps) {
  const methods = useForm<CreateTrainingDataType>({
    defaultValues: {
      traineePayments: [],
      volunteerPayments: [],
    },
  });

  const {
    control,
    handleSubmit,
    register,
    setValue,
    watch,
    formState: { errors, isSubmitting },
  } = methods;

  const { fields: traineeFields, replace: replaceTrainees } = useFieldArray({
    control,
    name: "traineePayments",
  });

  const { fields: volunteerFields, replace: replaceVolunteers } = useFieldArray(
    {
      control,
      name: "volunteerPayments",
    },
  );

  // Initialize form with training data
  useEffect(() => {
    if (open && training) {
      if (payerType === "TRAINEE") {
        const trainees = training.Trainees || [];
        const initialTraineePayments = trainees.map((trainee) => {
          const payment = training.TrainingPayment?.find(
            (p) =>
              p.payerType === "TRAINEE" &&
              (p.traineeId === trainee.customerId ||
                p.customerId === trainee.customerId),
          );

          return {
            participantId: trainee.customerId,
            price: payment?.basePrice
              ? (payment.basePrice / 100).toFixed(2).replace(".", ",")
              : "",
            additionalCost: payment?.additionalCost
              ? (payment.additionalCost / 100).toFixed(2).replace(".", ",")
              : "",
            additionalCostDescription: payment?.additionalCostDescription || "",
            paymentInfo: {
              paymentStatus: payment?.isCourtesy
                ? "Cortesia"
                : payment?.paymentStatus || "Pendente",
              firstPaymentDate: payment?.firstPaymentDate
                ? new Date(payment.firstPaymentDate)
                : null,
              firstPaymentAmount: payment?.firstPaymentAmount
                ? (payment.firstPaymentAmount / 100)
                  .toFixed(2)
                  .replace(".", ",")
                : "",
              firstPaymentStatus: payment?.firstPaymentStatus || "Pendente",
              firstPaymentMethod: payment?.firstPaymentMethod || "",
              secondPaymentAmount: payment?.secondPaymentAmount
                ? (payment.secondPaymentAmount / 100)
                  .toFixed(2)
                  .replace(".", ",")
                : "",
              secondPaymentStatus: payment?.secondPaymentStatus || "Pendente",
              secondPaymentMethod: payment?.secondPaymentMethod || "",
              secondPaymentDate: payment?.secondPaymentDate
                ? new Date(payment.secondPaymentDate)
                : null,
              wasRefunded: payment?.wasRefunded || false,
              refundAmount: payment?.refundAmount
                ? (payment.refundAmount / 100).toFixed(2).replace(".", ",")
                : "",
            },
          };
        });
        replaceTrainees(initialTraineePayments);
        // Clear volunteers to avoid confusion
        replaceVolunteers([]);
      } else {
        const volunteers = training.Volunteers || [];
        const initialVolunteerPayments = volunteers.map((volunteer) => {
          const payment = training.TrainingPayment?.find(
            (p) =>
              p.payerType === "VOLUNTEER" &&
              p.volunteerId === volunteer.volunteerId,
          );

          return {
            participantId: volunteer.volunteerId,
            price: payment?.totalPrice
              ? (payment.totalPrice / 100).toFixed(2).replace(".", ",")
              : "",
            additionalCost: "",
            additionalCostDescription: "",
            paymentInfo: {
              paymentStatus: payment?.isCourtesy
                ? "Cortesia"
                : payment?.paymentStatus || "Pendente",
              firstPaymentDate: payment?.firstPaymentDate
                ? new Date(payment.firstPaymentDate)
                : null,
              firstPaymentAmount: payment?.firstPaymentAmount
                ? (payment.firstPaymentAmount / 100)
                  .toFixed(2)
                  .replace(".", ",")
                : "",
              firstPaymentStatus: payment?.firstPaymentStatus || "Pendente",
              firstPaymentMethod: payment?.firstPaymentMethod || "",
              secondPaymentAmount: payment?.secondPaymentAmount
                ? (payment.secondPaymentAmount / 100)
                  .toFixed(2)
                  .replace(".", ",")
                : "",
              secondPaymentStatus: payment?.secondPaymentStatus || "Pendente",
              secondPaymentMethod: payment?.secondPaymentMethod || "",
              secondPaymentDate: payment?.secondPaymentDate
                ? new Date(payment.secondPaymentDate)
                : null,
              wasRefunded: payment?.wasRefunded || false,
              refundAmount: payment?.refundAmount
                ? (payment.refundAmount / 100).toFixed(2).replace(".", ",")
                : "",
            },
          };
        });
        replaceVolunteers(initialVolunteerPayments);
        // Clear trainees
        replaceTrainees([]);
      }
    }
  }, [ open, training, payerType, replaceTrainees, replaceVolunteers ]);

  const participants =
    payerType === "TRAINEE"
      ? training.Trainees?.map((t) => ({
        id: t.customerId,
        name: t.fullname,
      })) || []
      : training.Volunteers?.map((v) => ({
        id: v.volunteerId,
        name: v.name,
      })) || [];

  const onSubmit = async (data: CreateTrainingDataType) => {
    try {
      const payments =
        payerType === "TRAINEE" ? data.traineePayments : data.volunteerPayments;

      if (!payments || payments.length === 0) {
        toast.info("Nenhum participante para atualizar.");
        onOpenChange(false);
        return;
      }

      // We need to update each participant individually
      const updatePromises = payments.map(async (p) => {
        // Find existing payment to preserve other fields if needed,
        // essentially we are overwriting financial fields but keeping others safe
        const existingPayment = training.TrainingPayment?.find(
          (ep) =>
            ep.payerType === payerType &&
            (payerType === "TRAINEE"
              ? ep.traineeId === p.participantId ||
                ep.customerId === p.participantId
              : ep.volunteerId === p.participantId),
        );

        const basePrice = parseStringToCents(p.price || "0");
        const additionalCost =
          payerType === "TRAINEE"
            ? parseStringToCents(p.additionalCost || "0")
            : 0;
        const totalPrice = basePrice + additionalCost;

        const payload: UpdateTrainingPayload = {
          trainingStatus: training.trainingStatus,
          payerType: payerType,
          traineeId: payerType === "TRAINEE" ? p.participantId : undefined,
          customerId: payerType === "TRAINEE" ? p.participantId : undefined,
          volunteerId: payerType === "VOLUNTEER" ? p.participantId : undefined,

          TrainingPayment: {
            basePrice: basePrice,
            additionalCost: additionalCost,
            additionalCostDescription: p.additionalCostDescription,
            totalPrice: totalPrice,

            // Payment info
            paymentStatus:
              p.paymentInfo.paymentStatus === "Cortesia"
                ? "Pago"
                : p.paymentInfo.paymentStatus || "Pendente",

            firstPaymentAmount: parseStringToCents(
              String(p.paymentInfo.firstPaymentAmount || "0"),
            ),
            firstPaymentDate: p.paymentInfo.firstPaymentDate
              ? new Date(p.paymentInfo.firstPaymentDate)
              : null,
            firstPaymentMethod: p.paymentInfo.firstPaymentMethod || null,
            firstPaymentStatus: p.paymentInfo.firstPaymentStatus || "Pendente",

            secondPaymentAmount: parseStringToCents(
              String(p.paymentInfo.secondPaymentAmount || "0"),
            ),
            secondPaymentDate: p.paymentInfo.secondPaymentDate
              ? new Date(p.paymentInfo.secondPaymentDate)
              : null,
            secondPaymentMethod: p.paymentInfo.secondPaymentMethod || null,
            secondPaymentStatus:
              p.paymentInfo.secondPaymentStatus || "Pendente",

            // Preserve other fields but update isCourtesy based on selection
            isCourtesy:
              p.paymentInfo.paymentStatus === "Cortesia"
                ? true
                : p.paymentInfo.paymentStatus === "Pendente" ||
                    p.paymentInfo.paymentStatus === "Pago" ||
                    p.paymentInfo.paymentStatus === "Parcial"
                  ? false // Explicitly false if changed to a paid status
                  : existingPayment?.isCourtesy || false, // Fallback for other statuses? Actually better to be strict
            wasRefunded: p.paymentInfo.wasRefunded || false,
            refundAmount: parseStringToCents(
              String(p.paymentInfo.refundAmount || "0"),
            ),
            paymentMode: existingPayment?.paymentMode || "AVista",
          },
        };

        return UpdateTraining({
          trainingId: training.trainingId,
          body: payload as any,
        });
      });

      const results = await Promise.all(updatePromises);

      const hasError = results.some((r) => r.statusCode !== 200);

      if (!hasError) {
        toast.success("Valores atualizados com sucesso!");
        queryClient.invalidateQueries({ queryKey: [ "get-all-trainings" ] });

        // Ideally we should merge the results to update the selected training locally
        // For now, we return the last result's data or trigger a refetch
        if (results.length > 0 && results[results.length - 1].data) {
          onSuccess(results[results.length - 1].data!);
        }
        onOpenChange(false);
      } else {
        toast.warning("Alguns participantes podem não ter sido atualizados.");
      }
    } catch (error) {
      console.error(error);
      toast.error("Erro ao atualizar valores.");
    }
  };

  return (
    <Dialog open={ open } onOpenChange={ onOpenChange }>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto bg-card">
        <DialogHeader>
          <DialogTitle>
            Gerenciar Financeiro (
            {payerType === "TRAINEE" ? "Alunos" : "Pacientes Modelo"})
          </DialogTitle>
        </DialogHeader>

        <FormProvider { ...methods }>
          <form onSubmit={ handleSubmit(onSubmit) } className="space-y-6">
            <div className="border rounded-md p-5 bg-muted/10 shadow-sm">
              <FinancialInputSection
                control={ control }
                register={ register }
                setValue={ setValue }
                watch={ watch }
                errors={ errors }
                participants={ participants }
                type={ payerType === "TRAINEE" ? "trainee" : "volunteer" }
                fields={
                  payerType === "TRAINEE" ? traineeFields : volunteerFields
                }
              />
            </div>

            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={ () => onOpenChange(false) }
              >
                Cancelar
              </Button>
              <Button type="submit" disabled={ isSubmitting }>
                {isSubmitting && (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                )}
                Salvar Alterações
              </Button>
            </DialogFooter>
          </form>
        </FormProvider>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import {
  Control,
  UseFormRegister,
  UseFormSetValue,
  UseFormWatch,
  FieldErrors,
  Path,
} from "react-hook-form";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";
import PriceInput from "@/components/shared/PriceInput";
import { Textarea } from "@/components/ui/textarea";
import { TrainingPaymentSection } from "./TrainingPaymentSection";
import { CreateTrainingDataType } from "@/lib/zod/CreateTrainingValidation";

interface Participant {
  id: string;
  name: string;
}

interface FinancialInputSectionProps {
  control: Control<CreateTrainingDataType>;
  register: UseFormRegister<CreateTrainingDataType>;
  setValue: UseFormSetValue<CreateTrainingDataType>;
  watch: UseFormWatch<CreateTrainingDataType>;
  errors: FieldErrors<CreateTrainingDataType>;
  participants: Participant[];
  type: "trainee" | "volunteer";
  fields: any[]; // eslint-disable-line @typescript-eslint/no-explicit-any
}

// Helper para tratar string de moeda (ex: "1.000,00")
const parseCurrencyToFloat = (
  value: string | number | null | undefined,
): number => {
  if (!value) return 0;
  if (typeof value === "number") return value;
  // Remove tudo que não é dígito ou vírgula
  const cleanString = value.replace(/[^\d,]/g, "").replace(",", ".");
  return parseFloat(cleanString) || 0;
};

export function FinancialInputSection({
  control,
  register,
  setValue,
  watch,
  errors,
  participants,
  type,
  fields,
}: FinancialInputSectionProps) {
  const fieldName =
    type === "trainee" ? "traineePayments" : "volunteerPayments";

  const [ selectedParticipantId, setSelectedParticipantId ] = useState<
    string | null
  >(participants.length > 0 ? participants[0].id : null);

  const [ isReplicating, setIsReplicating ] = useState(false);

  useEffect(() => {
    if (participants.length > 0) {
      if (
        !selectedParticipantId ||
        !participants.find((p) => p.id === selectedParticipantId)
      ) {
        setSelectedParticipantId(participants[0].id);
      }
    } else {
      setSelectedParticipantId(null);
    }
  }, [ participants, selectedParticipantId ]);

  const selectedIndex = fields.findIndex(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (field: any) => field.participantId === selectedParticipantId,
  );

  // Watch current participant's values
  const currentPrice = watch(
    `${fieldName}.${selectedIndex}.price` as Path<CreateTrainingDataType>,
  );
  const currentAddCost = watch(
    `${fieldName}.${selectedIndex}.additionalCost` as Path<CreateTrainingDataType>,
  );
  const currentAddDesc = watch(
    `${fieldName}.${selectedIndex}.additionalCostDescription` as Path<CreateTrainingDataType>,
  );
  const currentPaymentInfo = watch(
    `${fieldName}.${selectedIndex}.paymentInfo` as Path<CreateTrainingDataType>,
  );

  // Replicate effect
  useEffect(() => {
    if (isReplicating && selectedIndex !== -1) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      fields.forEach((field: any, index) => {
        if (index === selectedIndex) return;

        // Check current payment status of the target field
        // We use fields[index] data if available, but for dynamic form validity we might need to rely on watch if the field data isn't updating in real-time,
        // HOWEVER, useFieldArray fields are snapshots. Let's try to get the current value from the form state if possible to be safe,
        // or rely on field.paymentInfo if initialized correctly.
        // Actually, since we are inside a form, `watch` on specific index is safer for current state.

        // WATCH OUT: We cannot call 'watch' inside this loop (hooks rules).
        // We need to access the current value using `methods.getValues()` if we had access to methods,
        // OR we can trust that `field.paymentInfo` has the initial state and if it changed it should be in the form state.
        // Since we don't have getValues here, we might need to rely on `fields` snapshot which is updated on re-render,
        // OR pass getValues from parent OR standard solution: use `watch` for the whole array outside the effect?
        // Watching the whole array might be heavy.

        // Better approach: We can check the defaultValue or the current value if we had it.
        // But wait, `fields` from useFieldArray contains the values.
        // Let's check `field.paymentInfo?.paymentStatus`.

        const currentStatus = field.paymentInfo?.paymentStatus;
        if (currentStatus === "Pago" || currentStatus === "Parcial") {
          return;
        }

        // Only update if different to avoid potential loops (though hook form is robust)
        setValue(
          `${fieldName}.${index}.price` as Path<CreateTrainingDataType>,
          currentPrice,
        );

        setValue(
          `${fieldName}.${index}.additionalCost` as Path<CreateTrainingDataType>,
          currentAddCost,
        );
        setValue(
          `${fieldName}.${index}.additionalCostDescription` as Path<CreateTrainingDataType>,
          currentAddDesc,
        );
      });
    }
  }, [
    isReplicating,
    selectedIndex,
    currentPrice,
    currentAddCost,
    currentAddDesc,
    // JSON.stringify(currentPaymentInfo), - disabling deps check to avoid complexity warning
    fields,
    fieldName,
    setValue,

    // currentPaymentInfo - omitted from strict dep check due to deep object comparison complexity, handled by re-renders
  ]);

  if (participants.length === 0) {
    return (
      <div className="text-sm text-muted-foreground italic p-4">
        Nenhum participante selecionado.
      </div>
    );
  }

  const isSelectedTrainee = type === "trainee";

  return (
    <div className="flex flex-col md:flex-row gap-4 h-full min-h-[400px]">
      {/* Left Col: List of Participants */}
      <div className="w-full md:w-1/3 border-r pr-4 space-y-2">
        <Label className="text-xs font-semibold uppercase text-muted-foreground mb-2 block">
          Participantes
        </Label>
        <div className="space-y-1 max-h-[400px] overflow-y-auto">
          {participants.map((p, index) => (
            <div
              key={ `${p.id}-${index}` }
              onClick={ () => setSelectedParticipantId(p.id) }
              className={ cn(
                "cursor-pointer px-3 py-2 rounded-md text-sm transition-colors flex items-center justify-between",
                selectedParticipantId === p.id
                  ? "bg-primary/10 text-primary font-medium"
                  : "hover:bg-muted",
              ) }
            >
              <span>{p.name}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Right Col: Inputs */}
      <div className="w-full md:w-2/3 pl-0 md:pl-2">
        {selectedIndex !== -1 && (
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <h4 className="font-semibold text-sm">
                {participants.find((p) => p.id === selectedParticipantId)?.name}
              </h4>

              <div className="flex items-center space-x-2">
                <Checkbox
                  id={ `replicate-${type}` }
                  checked={ isReplicating }
                  onCheckedChange={ (checked) =>
                    setIsReplicating(checked === true)
                  }
                />
                <label
                  htmlFor={ `replicate-${type}` }
                  className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70 flex flex-col"
                >
                  Replicar para todos
                  <span className="text-xs text-muted-foreground">
                    (exceto pagos e parciais)
                  </span>
                </label>
              </div>
            </div>

            <div className="space-y-4">
              {/* Calculate disabled state */}
              {(() => {
                const currentStatus = (currentPaymentInfo as any)
                  ?.paymentStatus;
                const isDisabled =
                  currentStatus === "Pago" ||
                  currentStatus === "Parcial" ||
                  currentStatus === "Cortesia";

                return (
                  <>
                    {/* Price */}
                    <div className="space-y-2">
                      <Label>Valor Base</Label>
                      <PriceInput
                        withLabel={ false }
                        register={ register(
                          `${fieldName}.${selectedIndex}.price` as Path<CreateTrainingDataType>,
                        ) }
                        value={
                          watch(
                            `${fieldName}.${selectedIndex}.price` as Path<CreateTrainingDataType>,
                          )?.toString() ?? ""
                        }
                        setValue={ setValue }
                        name={
                          `${fieldName}.${selectedIndex}.price` as Path<CreateTrainingDataType>
                        }
                        placeholder="R$ 0,00 "
                        disabled={ isDisabled }
                      />
                    </div>

                    {/* Additional Costs */}
                    {isSelectedTrainee && (
                      <div className="bg-yellow-50 dark:bg-yellow-900/10 p-4 rounded-md border border-yellow-200 dark:border-yellow-900/50 space-y-3">
                        <div className="space-y-2">
                          <Label className="text-yellow-800 dark:text-yellow-200 text-xs font-bold uppercase tracking-wide">
                            Custos Operacionais Extras
                          </Label>
                          <div className="grid grid-cols-1 gap-4">
                            <PriceInput
                              withLabel={ false }
                              register={ register(
                                `${fieldName}.${selectedIndex}.additionalCost` as Path<CreateTrainingDataType>,
                              ) }
                              value={
                                watch(
                                  `${fieldName}.${selectedIndex}.additionalCost` as Path<CreateTrainingDataType>,
                                )?.toString() ?? ""
                              }
                              setValue={ setValue }
                              name={
                                `${fieldName}.${selectedIndex}.additionalCost` as Path<CreateTrainingDataType>
                              }
                              placeholder="Valor:  R$ 0,00"
                              disabled={ isDisabled }
                            />
                            <Textarea
                              { ...register(
                                `${fieldName}.${selectedIndex}.additionalCostDescription` as Path<CreateTrainingDataType>,
                              ) }
                              placeholder="Descrição: Taxa de sala, material..."
                              className="resize-none min-h-[40px]"
                              rows={ 1 }
                              disabled={ isDisabled }
                              value={
                                (watch(
                                  `${fieldName}.${selectedIndex}.additionalCostDescription` as Path<CreateTrainingDataType>,
                                ) as string) || ""
                              }
                            />
                          </div>
                        </div>
                      </div>
                    )}
                    {/* Payment Info Section reused */}
                    <TrainingPaymentSection
                      prefix={ `${fieldName}.${selectedIndex}` }
                      label="Detalhes do Pagamento"
                      totalValue={
                        parseCurrencyToFloat(
                          currentPrice as unknown as string,
                        ) +
                        parseCurrencyToFloat(
                          currentAddCost as unknown as string,
                        )
                      }
                      disabled={ isDisabled }
                    />
                  </>
                );
              })()}
            </div>
          </div>
        )}
        {selectedIndex === -1 && (
          <div className="flex items-center justify-center h-full text-muted-foreground text-sm">
            Selecione um participante para configurar.
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { DollarSign, Loader2 } from "lucide-react";
import { Training } from "@/utils/@types/training";
import { UpdateTraining } from "@/services/trainings.service";
import { centsToString } from "@/utils/centsToString";
import { parseStringToCents } from "@/utils/parseStringToCents";
import { toast } from "sonner";
import { queryClient } from "@/app/(main)/layout";
import PriceInput from "@/components/shared/PriceInput";

interface UpdateParticipantValuesDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  selectedTraining: Training | null;
  setSelectedTraining?: (training: Training) => void;
  payerType: "TRAINEE" | "VOLUNTEER";
  participantId: string;
  currentPayment: any;
}

export function UpdateParticipantValuesDialog({
  open,
  onOpenChange,
  selectedTraining,
  setSelectedTraining,
  payerType,
  participantId,
  currentPayment,
}: UpdateParticipantValuesDialogProps) {
  const [ basePrice, setBasePrice ] = useState("0,00");
  const [ additionalCost, setAdditionalCost ] = useState("0,00");
  const [ additionalCostDescription, setAdditionalCostDescription ] =
    useState("");
  const [ isSubmitting, setIsSubmitting ] = useState(false);

  useEffect(() => {
    if (open && currentPayment) {
      setBasePrice(centsToString(currentPayment.basePrice || 0));
      setAdditionalCost(centsToString(currentPayment.additionalCost || 0));
      setAdditionalCostDescription(
        currentPayment.additionalCostDescription || "",
      );
    } else if (open) {
      // Defaults if no payment record exists yet (should be rare given getSafePaymentData logic)
      setBasePrice("0,00");
      setAdditionalCost("0,00");
      setAdditionalCostDescription("");
    }
  }, [ open, currentPayment ]);

  const handleSave = async () => {
    if (!selectedTraining) return;

    setIsSubmitting(true);
    try {
      const basePriceCents = parseStringToCents(basePrice);
      const additionalCostCents = parseStringToCents(additionalCost);
      const totalPriceCents = basePriceCents + additionalCostCents;

      const currentStatus = currentPayment?.paymentStatus;
      const effectivePaymentStatus =
        currentStatus === "Cortesia" ? "Pago" : currentStatus || "Pendente";
      const effectiveIsCourtesy =
        currentPayment?.isCourtesy || currentStatus === "Cortesia";

      // Construct payload specifically to update values
      // We must preserve existing payment status/details so we don't reset them
      const payload = {
        trainingStatus: selectedTraining.trainingStatus,
        payerType: payerType,
        traineeId: payerType === "TRAINEE" ? participantId : undefined,
        customerId: payerType === "TRAINEE" ? participantId : undefined,
        volunteerId: payerType === "VOLUNTEER" ? participantId : undefined,
        isCourtesy: effectiveIsCourtesy,
        TrainingPayment: {
          ...currentPayment, // Spread existing payment to keep other fields
          basePrice: basePriceCents,
          additionalCost: additionalCostCents,
          additionalCostDescription: additionalCostDescription,
          totalPrice: totalPriceCents,
          // Ensure mandatory fields for UpdateTrainingPayload are present if currentPayment is undefined
          paymentStatus: effectivePaymentStatus,
          paymentMode: currentPayment?.paymentMode || "AVista",
          firstPaymentAmount: currentPayment?.firstPaymentAmount || 0,
          firstPaymentDate: currentPayment?.firstPaymentDate
            ? new Date(currentPayment.firstPaymentDate)
            : null,
          firstPaymentMethod: currentPayment?.firstPaymentMethod || null,
          firstPaymentStatus: currentPayment?.firstPaymentStatus || "Pendente",
          secondPaymentAmount: currentPayment?.secondPaymentAmount || 0,
          secondPaymentDate: currentPayment?.secondPaymentDate
            ? new Date(currentPayment.secondPaymentDate)
            : null,
          secondPaymentMethod: currentPayment?.secondPaymentMethod || null,
          secondPaymentStatus:
            currentPayment?.secondPaymentStatus || "Pendente",
        },
      };

      const response = await UpdateTraining({
        trainingId: selectedTraining.trainingId,
        body: payload as any, // Cast as any because UpdateTrainingPayload type in service might be loose or strict
      });

      if (response.statusCode === 200) {
        toast.success("Valores atualizados com sucesso!");
        queryClient.invalidateQueries({ queryKey: [ "get-all-trainings" ] });
        if (setSelectedTraining && response.data) {
          setSelectedTraining(response.data);
        }
        onOpenChange(false);
      } else {
        toast.warning(response.message || "Erro ao atualizar valores.");
      }
    } catch (error) {
      console.error(error);
      toast.error("Erro ao atualizar valores.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={ open } onOpenChange={ onOpenChange }>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <DollarSign className="w-5 h-5 text-primary" />
            Editar Valores
          </DialogTitle>
          <DialogDescription>
            Atualize o preço base e custos adicionais para este participante.
          </DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 py-4">
          <div className="grid gap-2">
            <Label htmlFor="basePrice">Preço Base Participant</Label>
            <PriceInput value={ basePrice } onChange={ setBasePrice } />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="additionalCost">Custos Adicionais</Label>
            <PriceInput value={ additionalCost } onChange={ setAdditionalCost } />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="description">Descrição dos Adicionais</Label>
            <Input
              id="description"
              value={ additionalCostDescription }
              onChange={ (e) => setAdditionalCostDescription(e.target.value) }
              placeholder="Ex: Material extra, deslocamento..."
            />
          </div>
        </div>
        <DialogFooter>
          <Button
            variant="outline"
            onClick={ () => onOpenChange(false) }
            disabled={ isSubmitting }
          >
            Cancelar
          </Button>
          <Button onClick={ handleSave } disabled={ isSubmitting }>
            {isSubmitting ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Salvando...
              </>
            ) : (
              "Salvar Alterações"
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
